import app from "flarum/forum/app";
function base() {
  return app.forum.attribute("apiUrl") + "/giveaways";
}
export function listGiveaways(page, filters) {
  if (page === void 0) {
    page = 1;
  }
  if (filters === void 0) {
    filters = {};
  }
  const q = new URLSearchParams();
  if (page > 1) q.set("page", String(page));
  if (filters.status) q.set("filter[status]", filters.status);
  if (filters.category) q.set("filter[category]", String(filters.category));
  const qs = q.toString();
  return app.request({
    method: "GET",
    url: base() + (qs ? "?".concat(qs) : "")
  });
}
export function showGiveaway(idOrSlug) {
  return app.request({
    method: "GET",
    url: "".concat(base(), "/").concat(idOrSlug)
  });
}
export function enterGiveaway(id) {
  return app.request({
    method: "POST",
    url: "".concat(base(), "/").concat(id, "/enter")
  });
}
export function listEntries(id, page) {
  if (page === void 0) {
    page = 1;
  }
  const q = page > 1 ? "?page=".concat(page) : "";
  return app.request({
    method: "GET",
    url: "".concat(base(), "/").concat(id, "/entries") + q,
    errorHandler: () => {}
  });
}
export function drawGiveaway(id) {
  return app.request({
    method: "POST",
    url: "".concat(base(), "/").concat(id, "/draw")
  });
}
export function claimGiveaway(id) {
  return app.request({
    method: "POST",
    url: "".concat(base(), "/").concat(id, "/claim")
  });
}
export function deleteGiveaway(id) {
  return app.request({
    method: "DELETE",
    url: "".concat(base(), "/").concat(id)
  });
}
export function cancelGiveaway(id) {
  return app.request({
    method: "POST",
    url: "".concat(base(), "/").concat(id, "/cancel")
  });
}

/** Publish a draft (draft → active). */
export function publishGiveaway(id) {
  return saveGiveaway({
    status: "active"
  }, id);
}
export function saveGiveaway(attributes, id) {
  return app.request({
    method: id ? "PATCH" : "POST",
    url: id ? "".concat(base(), "/").concat(id) : base(),
    body: {
      data: {
        attributes
      }
    }
  });
}
function catBase() {
  return app.forum.attribute("apiUrl") + "/giveaway-categories";
}
let categoriesCache = null;
let categoriesPromise = null;
export function getCachedCategories() {
  return categoriesCache;
}
export function invalidateCategoriesCache() {
  categoriesCache = null;
  categoriesPromise = null;
}
export function listCategories() {
  if (categoriesCache) {
    return Promise.resolve({
      data: categoriesCache
    });
  }
  if (!categoriesPromise) {
    // 同一时刻多个组件同时请求时只发一次
    categoriesPromise = app.request({
      method: "GET",
      url: catBase()
    }).then(res => {
      categoriesCache = res.data || [];
      return res;
    });
  }
  return categoriesPromise;
}
export function saveCategory(attributes, id) {
  invalidateCategoriesCache();
  return app.request({
    method: id ? "PATCH" : "POST",
    url: id ? "".concat(catBase(), "/").concat(id) : catBase(),
    body: {
      data: {
        attributes
      }
    }
  });
}
export function deleteCategory(id) {
  invalidateCategoriesCache();
  return app.request({
    method: "DELETE",
    url: "".concat(catBase(), "/").concat(id)
  });
}
flarum.reg.add('ygpynet-giveaways', 'common/api', { listGiveaways: listGiveaways,showGiveaway: showGiveaway,enterGiveaway: enterGiveaway,listEntries: listEntries,drawGiveaway: drawGiveaway,claimGiveaway: claimGiveaway,deleteGiveaway: deleteGiveaway,cancelGiveaway: cancelGiveaway,publishGiveaway: publishGiveaway,saveGiveaway: saveGiveaway,getCachedCategories: getCachedCategories,invalidateCategoriesCache: invalidateCategoriesCache,listCategories: listCategories,saveCategory: saveCategory,deleteCategory: deleteCategory, });